insert into public.lessons(id,path_id,type,category,title,subtitle,body,content,reward_xp,sort_order,is_published)
values
('web-html-02','web','multiple_choice','HTML structure','Choose a semantic landmark','Quick review · Beginner','Use the element that best describes the main content area.','{"question": "Which HTML element represents the dominant content of a document?", "options": [{"id": "a", "label": "<main>"}, {"id": "b", "label": "<section>"}, {"id": "c", "label": "<div>"}, {"id": "d", "label": "<aside>"}], "explanation": "The main element identifies the page’s dominant content. A page should normally have one visible main landmark.", "hint": "Look for the element whose name describes the page’s primary content.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,3,true),
('web-html-03','web','multiple_choice','HTML accessibility','Describe an informative image','Quick review · Beginner','Alternative text gives meaning to images when they cannot be seen.','{"question": "Which attribute provides text alternatives for an informative image?", "options": [{"id": "a", "label": "title"}, {"id": "b", "label": "alt"}, {"id": "c", "label": "src"}, {"id": "d", "label": "role"}], "explanation": "The alt attribute supplies a text alternative for an image.", "hint": "It is a two-letter attribute beginning with a.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,4,true),
('web-css-01','web','multiple_choice','CSS selectors','Target one class','Quick review · Beginner','Class selectors begin with a period.','{"question": "Which selector targets every element with class=\"card\"?", "options": [{"id": "a", "label": "#card"}, {"id": "b", "label": ".card"}, {"id": "c", "label": "card"}, {"id": "d", "label": "*card"}], "explanation": "A period introduces a class selector in CSS.", "hint": "A class selector starts with a dot.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,5,true),
('web-css-02','web','multiple_choice','CSS box model','Understand element width','Quick review · Beginner','The box model includes content, padding, border and margin.','{"question": "Which box-sizing value includes padding and border inside the declared width?", "options": [{"id": "a", "label": "content-box"}, {"id": "b", "label": "inherit"}, {"id": "c", "label": "border-box"}, {"id": "d", "label": "margin-box"}], "explanation": "With border-box, the declared width includes content, padding and border.", "hint": "Choose the value that makes width calculations easier.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,6,true),
('web-css-03','web','multiple_choice','CSS layout','Align items in a row','Quick review · Beginner','Flexbox is useful for one-dimensional layouts.','{"question": "Which declaration turns an element into a flex container?", "options": [{"id": "a", "label": "display: grid;"}, {"id": "b", "label": "position: flex;"}, {"id": "c", "label": "display: flex;"}, {"id": "d", "label": "flex: display;"}], "explanation": "display:flex establishes a flex formatting context for its children.", "hint": "The property is display and the value is flex.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,7,true),
('web-css-04','web','multiple_choice','Responsive design','Use a media query','Quick review · Beginner','Media queries apply styles when a condition matches the device or viewport.','{"question": "Which rule applies styles when the viewport is 600 pixels wide or less?", "options": [{"id": "a", "label": "@media (max-width: 600px) { ... }"}, {"id": "b", "label": "@screen 600px { ... }"}, {"id": "c", "label": "@responsive (600px) { ... }"}, {"id": "d", "label": "@media (min-width: 600px) { ... }"}], "explanation": "max-width:600px matches viewport widths at or below 600 pixels.", "hint": "Use max-width when the rule is meant for small screens.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,8,true),
('web-css-05','web','multiple_choice','CSS cascade','Understand specificity','Quick review · Beginner','More specific selectors usually take precedence when origin and importance are equal.','{"question": "Which selector has the greatest specificity?", "options": [{"id": "a", "label": "p"}, {"id": "b", "label": ".note"}, {"id": "c", "label": "#note"}, {"id": "d", "label": "article p"}], "explanation": "An ID selector has greater specificity than a class, element or compound element selector.", "hint": "Compare element, class and ID selector weight.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,9,true),
('web-html-04','web','multiple_choice','HTML forms','Connect a label to an input','Quick review · Beginner','A label improves form usability and accessibility.','{"question": "How should a label be associated with an input whose id is \"email\"?", "options": [{"id": "a", "label": "Give the label name=\"email\""}, {"id": "b", "label": "Set label for=\"email\""}, {"id": "c", "label": "Set input label=\"email\""}, {"id": "d", "label": "Put the label after the form"}], "explanation": "The label for attribute must match the input id.", "hint": "The label uses the for attribute.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,10,true),
('logic-02','programming','multiple_choice','JavaScript variables','Choose a reassignment-friendly declaration','Quick review · Beginner','Use let for bindings that need reassignment.','{"question": "Which declaration allows the variable value to be reassigned?", "options": [{"id": "a", "label": "const score = 10;"}, {"id": "b", "label": "let score = 10;"}, {"id": "c", "label": "static score = 10;"}, {"id": "d", "label": "fixed score = 10;"}], "explanation": "let creates a block-scoped variable that can be reassigned.", "hint": "Avoid const when the binding itself must change.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,2,true),
('logic-03','programming','multiple_choice','Conditionals','Evaluate a comparison','Quick review · Beginner','A comparison expression produces a Boolean value.','{"question": "What is the result of 7 >= 7 in JavaScript?", "options": [{"id": "a", "label": "false"}, {"id": "b", "label": "undefined"}, {"id": "c", "label": "true"}, {"id": "d", "label": "null"}], "explanation": "The >= operator includes equality, so 7 is greater than or equal to 7.", "hint": "The equals case is included.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,3,true),
('logic-04','programming','multiple_choice','Loops','Count a loop iteration','Quick review · Beginner','A for loop can repeat while its condition remains true. Example: for (let i = 0; i < 4; i++) { work(); }','{"question": "How many times does this loop run?", "options": [{"id": "a", "label": "3"}, {"id": "b", "label": "4"}, {"id": "c", "label": "5"}, {"id": "d", "label": "Forever"}], "explanation": "The values of i are 0, 1, 2 and 3: four iterations.", "hint": "Start at zero and stop before four.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,4,true),
('logic-05','programming','multiple_choice','Functions','Return a value','Quick review · Beginner','return sends a value back to the caller.','{"question": "What does the return keyword do inside a function?", "options": [{"id": "a", "label": "Repeats the function"}, {"id": "b", "label": "Sends a value back and ends that function call"}, {"id": "c", "label": "Prints text to the screen"}, {"id": "d", "label": "Creates a global variable"}], "explanation": "return ends the current function execution and provides the specified value.", "hint": "It gives the caller a result.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,5,true),
('logic-06','programming','multiple_choice','Arrays','Read an array index','Quick review · Beginner','JavaScript arrays use zero-based indexing.','{"question": "What does items[0] access?", "options": [{"id": "a", "label": "The first item"}, {"id": "b", "label": "The second item"}, {"id": "c", "label": "The last item"}, {"id": "d", "label": "The array length"}], "explanation": "An array’s first element is at index zero.", "hint": "Counting starts at zero.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,6,true),
('logic-07','programming','multiple_choice','Equality','Compare without type coercion','Quick review · Beginner','Strict equality checks value and type.','{"question": "Which operator checks equality without converting operand types?", "options": [{"id": "a", "label": "="}, {"id": "b", "label": "=="}, {"id": "c", "label": "==="}, {"id": "d", "label": "!="}], "explanation": "=== performs strict equality without type coercion.", "hint": "It uses three equals signs.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,7,true),
('logic-08','programming','multiple_choice','Objects','Access an object property','Quick review · Beginner','Properties can be accessed with dot notation.','{"question": "Given const learner = {name: \"Ama\"}, how do you read the name?", "options": [{"id": "a", "label": "learner->name"}, {"id": "b", "label": "learner.name"}, {"id": "c", "label": "learner(name)"}, {"id": "d", "label": "name.learner"}], "explanation": "Dot notation reads a named property from an object.", "hint": "Write the object name, a dot, then the property.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,8,true),
('logic-09','programming','multiple_choice','Errors','Handle a possible exception','Quick review · Beginner','try/catch handles exceptions from a block of code.','{"question": "Which block handles an exception thrown inside a try block?", "options": [{"id": "a", "label": "finally only"}, {"id": "b", "label": "catch"}, {"id": "c", "label": "switch"}, {"id": "d", "label": "for"}], "explanation": "catch receives the thrown error when the try block fails.", "hint": "It is paired with try.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,9,true),
('database-02','database','multiple_choice','SQL filtering','Filter rows with WHERE','Quick review · Beginner','WHERE limits the rows returned by a query.','{"question": "Which clause filters students to those in the IT programme?", "options": [{"id": "a", "label": "ORDER BY programme"}, {"id": "b", "label": "WHERE programme = ''IT''"}, {"id": "c", "label": "GROUP BY programme"}, {"id": "d", "label": "HAVING programme"}], "explanation": "WHERE applies a row-level condition before grouping.", "hint": "Use the clause designed to filter rows.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,2,true),
('database-03','database','multiple_choice','SQL sorting','Sort newest records first','Quick review · Beginner','ORDER BY sorts result rows.','{"question": "Which query sorts records from newest to oldest using created_at?", "options": [{"id": "a", "label": "ORDER BY created_at ASC"}, {"id": "b", "label": "SORT created_at DESC"}, {"id": "c", "label": "ORDER BY created_at DESC"}, {"id": "d", "label": "GROUP BY created_at DESC"}], "explanation": "DESC sorts values in descending order, placing later timestamps first.", "hint": "Use ORDER BY with DESC.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,3,true),
('database-04','database','multiple_choice','SQL aggregation','Count records','Quick review · Beginner','COUNT(*) counts rows in the result set.','{"question": "Which expression counts all rows in a group?", "options": [{"id": "a", "label": "SUM(*)"}, {"id": "b", "label": "COUNT(*)"}, {"id": "c", "label": "TOTAL(*)"}, {"id": "d", "label": "AVG(*)"}], "explanation": "COUNT(*) returns the number of rows, including rows with null columns.", "hint": "Use the aggregate that counts rows.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,4,true),
('database-05','database','multiple_choice','SQL joins','Match related tables','Quick review · Beginner','A join combines rows based on a related column.','{"question": "Which join returns only rows with matching keys in both tables?", "options": [{"id": "a", "label": "LEFT JOIN"}, {"id": "b", "label": "FULL OUTER JOIN"}, {"id": "c", "label": "INNER JOIN"}, {"id": "d", "label": "CROSS JOIN"}], "explanation": "INNER JOIN returns rows where the join condition matches in both tables.", "hint": "Choose the join that keeps matching pairs only.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,5,true),
('database-06','database','multiple_choice','Relational keys','Identify a primary key','Quick review · Beginner','A primary key uniquely identifies each row.','{"question": "Which statement about a primary key is correct?", "options": [{"id": "a", "label": "It can contain duplicate values"}, {"id": "b", "label": "It uniquely identifies each row and cannot be NULL"}, {"id": "c", "label": "It must always be a text column"}, {"id": "d", "label": "It is used only for sorting"}], "explanation": "A primary key enforces uniqueness and non-null identity for each row.", "hint": "It must identify one row unambiguously.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,6,true),
('database-07','database','multiple_choice','Relational keys','Understand a foreign key','Quick review · Beginner','A foreign key enforces a relationship to a referenced key.','{"question": "What is the main purpose of a foreign key?", "options": [{"id": "a", "label": "To encrypt a table"}, {"id": "b", "label": "To link rows and enforce referential integrity"}, {"id": "c", "label": "To sort records automatically"}, {"id": "d", "label": "To replace every index"}], "explanation": "A foreign key ensures referenced values exist in the related parent table.", "hint": "Think about maintaining valid relationships between tables.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,7,true),
('database-08','database','multiple_choice','Normalization','Reduce repeating groups','Quick review · Beginner','First normal form requires atomic values and no repeating groups.','{"question": "Which design best follows first normal form?", "options": [{"id": "a", "label": "One column stores \"HTML, CSS, SQL\" as a list"}, {"id": "b", "label": "Each skill is stored in its own row in a related table"}, {"id": "c", "label": "Every table has one column only"}, {"id": "d", "label": "All values are stored in one JSON string"}], "explanation": "Atomic values and no repeating groups are central to 1NF.", "hint": "Avoid storing a list of multiple values in one field.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,8,true),
('database-09','database','multiple_choice','Database indexes','Speed up lookups','Quick review · Beginner','Indexes can improve reads but add storage and write overhead.','{"question": "What is a common purpose of an index on student_id?", "options": [{"id": "a", "label": "Make queries filtering by student_id faster"}, {"id": "b", "label": "Automatically encrypt student_id"}, {"id": "c", "label": "Prevent all duplicate rows in every column"}, {"id": "d", "label": "Replace the primary key"}], "explanation": "An index helps the database locate matching rows more efficiently.", "hint": "Think about how a database finds matching values.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,9,true),
('security-02','security','multiple_choice','Phishing','Spot a suspicious message','Quick review · Beginner','Phishing attempts to trick people into revealing information or opening malicious links.','{"question": "Which message is the strongest phishing warning sign?", "options": [{"id": "a", "label": "A known lecturer sends a timetable from the university portal"}, {"id": "b", "label": "An unexpected message demands your password through an unfamiliar link"}, {"id": "c", "label": "A teammate shares a document in the approved workspace"}, {"id": "d", "label": "A system notification appears inside the official app"}], "explanation": "Urgency plus an unfamiliar credential-collection link is a strong phishing indicator.", "hint": "Be careful when a message pressures you to enter credentials.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,2,true),
('security-03','security','multiple_choice','Authentication','Add another factor','Quick review · Beginner','MFA requires additional proof beyond a password.','{"question": "Which option is an example of multi-factor authentication?", "options": [{"id": "a", "label": "Password plus a one-time authenticator code"}, {"id": "b", "label": "Two different passwords"}, {"id": "c", "label": "Username plus email address"}, {"id": "d", "label": "A longer username"}], "explanation": "A password plus a code from a separate authenticator is two different factors.", "hint": "One factor is something you know; the other can be something you have.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,3,true),
('security-04','security','multiple_choice','Encryption','Protect data in transit','Quick review · Beginner','TLS protects data exchanged between a client and server.','{"question": "What does HTTPS primarily provide for browser-to-server traffic?", "options": [{"id": "a", "label": "A guarantee that a website is honest"}, {"id": "b", "label": "Encrypted transport and server authentication using TLS"}, {"id": "c", "label": "A guarantee that downloads contain no malware"}, {"id": "d", "label": "Automatic backups"}], "explanation": "HTTPS uses TLS to protect the connection and authenticate the server.", "hint": "HTTPS is HTTP secured with TLS.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,4,true),
('security-05','security','multiple_choice','Password storage','Store passwords safely','Quick review · Beginner','Passwords should be stored as salted password hashes using a suitable password hashing algorithm.','{"question": "How should an application store user passwords?", "options": [{"id": "a", "label": "As plain text"}, {"id": "b", "label": "Reversibly encrypted with a shared key"}, {"id": "c", "label": "As salted hashes using a password-hashing algorithm"}, {"id": "d", "label": "In a public profile table"}], "explanation": "Password-hashing algorithms are designed to make offline guessing expensive; unique salts prevent identical passwords from sharing identical hashes.", "hint": "Do not store passwords in a form that can simply be read back.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,5,true),
('security-06','security','multiple_choice','Access control','Apply least privilege','Quick review · Beginner','Users and processes should receive only permissions required for their tasks.','{"question": "What does the principle of least privilege recommend?", "options": [{"id": "a", "label": "Give every user administrator rights"}, {"id": "b", "label": "Grant only the minimum access needed to perform assigned work"}, {"id": "c", "label": "Disable all authentication"}, {"id": "d", "label": "Share one account among a team"}], "explanation": "Least privilege limits the impact of mistakes and compromised accounts.", "hint": "Access should be no broader than necessary.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,6,true),
('security-07','security','multiple_choice','Updates','Reduce known vulnerabilities','Quick review · Beginner','Security updates often fix publicly known software weaknesses.','{"question": "Why should operating systems and applications receive security updates?", "options": [{"id": "a", "label": "To remove every possible threat"}, {"id": "b", "label": "To patch known vulnerabilities and reduce exposure"}, {"id": "c", "label": "To make passwords unnecessary"}, {"id": "d", "label": "To disable access logs"}], "explanation": "Patching closes known weaknesses before attackers can exploit them.", "hint": "Updates often include fixes for security defects.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,7,true),
('security-08','security','multiple_choice','Backups','Recover from data loss','Quick review · Beginner','Backups should be tested and protected from the same failures as production systems.','{"question": "Which practice makes backups more reliable?", "options": [{"id": "a", "label": "Keep one backup on the same laptop only"}, {"id": "b", "label": "Never test restore procedures"}, {"id": "c", "label": "Maintain separate protected copies and test restoration regularly"}, {"id": "d", "label": "Use the same administrator password everywhere"}], "explanation": "Separate protected copies plus restore tests provide evidence that recovery works.", "hint": "A backup is useful only if it can be restored.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,8,true),
('security-09','security','multiple_choice','Network safety','Use public Wi-Fi carefully','Quick review · Beginner','Public networks may be untrusted.','{"question": "When using public Wi-Fi, which action is safest?", "options": [{"id": "a", "label": "Disable device updates"}, {"id": "b", "label": "Use HTTPS, avoid untrusted downloads and use a trusted VPN when appropriate"}, {"id": "c", "label": "Share files with everyone on the network"}, {"id": "d", "label": "Turn off the device firewall"}], "explanation": "Encrypted connections and cautious network use reduce exposure on untrusted Wi-Fi.", "hint": "Treat public networks as untrusted.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,9,true),
('tools-01','tools','multiple_choice','Git basics','Start version control','Quick review · Beginner','Git tracks changes in a project repository.','{"question": "Which command initializes a new Git repository in the current folder?", "options": [{"id": "a", "label": "git start"}, {"id": "b", "label": "git init"}, {"id": "c", "label": "git create"}, {"id": "d", "label": "git open"}], "explanation": "git init creates a new local repository in the current directory.", "hint": "It is a short command ending in init.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,1,true),
('tools-02','tools','multiple_choice','Git workflow','Check changed files','Quick review · Beginner','git status reports the state of the working tree and staging area.','{"question": "Which command shows modified, staged and untracked files?", "options": [{"id": "a", "label": "git status"}, {"id": "b", "label": "git push"}, {"id": "c", "label": "git log --all"}, {"id": "d", "label": "git branch --delete"}], "explanation": "git status summarizes changes and the current branch state.", "hint": "Use the command that reports repository status.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,2,true),
('tools-03','tools','multiple_choice','Git staging','Stage a file','Quick review · Beginner','Staging prepares changes for the next commit.','{"question": "Which command stages index.html for the next commit?", "options": [{"id": "a", "label": "git commit index.html"}, {"id": "b", "label": "git add index.html"}, {"id": "c", "label": "git push index.html"}, {"id": "d", "label": "git stage --commit index.html"}], "explanation": "git add places the specified file into the staging area.", "hint": "The command begins with add.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,3,true),
('tools-04','tools','multiple_choice','Git commits','Save a snapshot','Quick review · Beginner','A commit records staged changes with a message.','{"question": "Which command creates a commit with the message \"Add profile page\"?", "options": [{"id": "a", "label": "git save \"Add profile page\""}, {"id": "b", "label": "git commit -m \"Add profile page\""}, {"id": "c", "label": "git push -m \"Add profile page\""}, {"id": "d", "label": "git add -m \"Add profile page\""}], "explanation": "git commit -m records the staged snapshot and its description.", "hint": "Use commit and the -m option.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,4,true),
('tools-05','tools','multiple_choice','Git remotes','Send commits to a remote','Quick review · Beginner','git push sends local commits to a remote repository.','{"question": "Which command pushes the current branch named main to origin?", "options": [{"id": "a", "label": "git pull origin main"}, {"id": "b", "label": "git push origin main"}, {"id": "c", "label": "git clone origin main"}, {"id": "d", "label": "git fetch --delete main"}], "explanation": "git push origin main publishes the local main branch to origin.", "hint": "Push sends your branch to the named remote.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,5,true),
('tools-06','tools','multiple_choice','Git branches','Create a branch','Quick review · Beginner','Branches let you work on changes separately.','{"question": "Which command creates and switches to a branch named feature/profile?", "options": [{"id": "a", "label": "git branch feature/profile"}, {"id": "b", "label": "git checkout -b feature/profile"}, {"id": "c", "label": "git merge feature/profile"}, {"id": "d", "label": "git reset feature/profile"}], "explanation": "git checkout -b creates the branch and checks it out.", "hint": "Use the option that both creates and switches.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,6,true),
('tools-07','tools','multiple_choice','Terminal navigation','Change directories','Quick review · Beginner','cd changes the current working directory.','{"question": "Which command moves into a folder named projects?", "options": [{"id": "a", "label": "ls projects"}, {"id": "b", "label": "cd projects"}, {"id": "c", "label": "mkdir projects"}, {"id": "d", "label": "pwd projects"}], "explanation": "cd changes the shell’s current directory.", "hint": "It stands for change directory.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,7,true),
('tools-08','tools','multiple_choice','Project documentation','Explain a repository','Quick review · Beginner','A README introduces a project and explains how to use it.','{"question": "Which file commonly explains a project, setup steps and usage?", "options": [{"id": "a", "label": "LICENSE"}, {"id": "b", "label": "README.md"}, {"id": "c", "label": "node_modules"}, {"id": "d", "label": ".env"}], "explanation": "README.md is the conventional project overview and setup guide.", "hint": "Look for the file usually shown on a repository homepage.", "difficulty": "beginner", "review_weight": 1}'::jsonb,25,8,true)
