-- 40 additional beginner study questions. The answer keys remain server-side.
create index if not exists lessons_path_sort_idx on public.lessons(path_id, sort_order, id);

on conflict (id) do update set path_id=excluded.path_id,type=excluded.type,category=excluded.category,
 title=excluded.title,subtitle=excluded.subtitle,body=excluded.body,content=excluded.content,
 reward_xp=excluded.reward_xp,sort_order=excluded.sort_order,is_published=excluded.is_published,updated_at=now();

on conflict (lesson_id) do update set correct_answer=excluded.correct_answer;

comment on index public.lessons_path_sort_idx is 'Supports ordered learning-path lesson loading in SkillSprint.';
